package br.edu.insper.transacoes;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="transactions") public class Transaction { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private Long clientId; @Column(nullable=false) private String clientEmail; @Column(nullable=false) private String stockCode; @Column(nullable=false) private Integer quantity; @Column(nullable=false,precision=19,scale=2) private BigDecimal unitPrice; @Column(nullable=false,precision=19,scale=2) private BigDecimal totalValue; @Column(nullable=false) private LocalDateTime transactedAt; protected Transaction(){} public Transaction(Long c,String e,String s,Integer q,BigDecimal p,LocalDateTime d){clientId=c;clientEmail=e;stockCode=s;quantity=q;unitPrice=p;totalValue=p.multiply(BigDecimal.valueOf(q));transactedAt=d;} public Long getId(){return id;} public Long getClientId(){return clientId;} public String getClientEmail(){return clientEmail;} public String getStockCode(){return stockCode;} public Integer getQuantity(){return quantity;} public BigDecimal getUnitPrice(){return unitPrice;} public BigDecimal getTotalValue(){return totalValue;} public LocalDateTime getTransactedAt(){return transactedAt;} }
